\[
\begin{gathered}
S=(a_{1}+a_{2}+a_{3}+\cdots+a_{2n+1})-2(a_{2}+a_{4}+\cdots+a_{2n}),\\
=\frac{\sin\frac{2n+1}{2}\alpha\cos\left((n+1)\alpha\right)}{\sin\frac{\alpha}{2}}-2\frac{\sin(n\alpha)\cos\left((n+1)\alpha\right)}{\sin\alpha}.
\end{gathered}
